	if add(2, 3) != 5 {
		t.Fatalf("add(2, 3) = %d, want 5", add(2, 3))
	}
}

func TestIsPalindrome(t *testing.T) {
	cases := []struct {
		input string
		want  bool
	}{
		{"racecar", true},
		{"level", true},
		{"a", true},
		{"", true},
		{"hello", false},
		{"racecarX", false},
	}
	for _, c := range cases {
		if got := isPalindrome(c.input); got != c.want {
			t.Errorf("isPalindrome(%q) = %t, want %t", c.input, got, c.want)
		}
	}
}

